SELECT u.id AS id, u.username AS username, u.display_name AS displayName, u.bio AS bio
FROM follows f
JOIN users u ON u.id = f.follower_id
WHERE f.followee_id = #{userId}
ORDER BY f.created_at DESC, u.id DESC
LIMIT #{limit}

